/// <summary>
///     The <c>AVACustInvoiceLineDbt_Extension</c> class is the extension for <c>CustInvoiceLine</c>
/// </summary>
[ExtensionOf(tableStr(CustInvoiceLine))]
final class AVACustInvoiceLineDbt_Extension
{
}

Method.Source:
/// <summary>
///     AVA <c>initFromCustInvoiceTable</c> method.
/// </summary>
/// <param name="custInvoiceTable">
///     <c>CustInvoiceTable</c> as type
/// </param>
public void initFromCustInvoiceTable(CustInvoiceTable custInvoiceTable)
{
    next initFromCustInvoiceTable(custInvoiceTable);

    if(custInvoiceTable.AVABonusInvoice == NoYes::Yes)
    {
        this.avaBonusInitFromCustInvoiceTable(custInvoiceTable);
    }
}

/// <summary>
///     AVA <c>avaBonusInitFromCustInvoiceTable</c> method.
/// </summary>
/// <param name="custInvoiceTable">
///     <c>CustInvoiceTable</c> as type
/// </param>
public void avaBonusInitFromCustInvoiceTable(CustInvoiceTable custInvoiceTable)
{
    this.AVASettlementFromDate  = custInvoiceTable.KCS_BOSSettlementFromDate;
    this.AVASettlementToDate    = custInvoiceTable.KCS_BOSSettlementToDate;
    this.AVABonusAllocationBase = custInvoiceTable.AVABonusAllocationBase;
    this.AVABonusCustAccount    = custInvoiceTable.AVABonusCustAccount;
    this.AVABonusAlliance       = custInvoiceTable.AVABonusAlliance;
}

/// <summary>
///     AVA <c>validateWrite</c> method.
/// </summary>
/// <returns>
///     <c>boolean</c> as return value
/// </returns>
public boolean validateWrite()
{
    boolean retVal;

    retVal = next validateWrite();

    retVal = retVal && this.avaBonusCheckValues();

    return retVal;
}

/// <summary>
///     AVA <c>avaBonusCheckValues</c> method.
/// </summary>
/// <param name="custInvoiceTable">
///     <c>CustInvoiceTable</c> as type
/// </param>
/// <returns>
///     <c>boolean</c> as return value
/// </returns>
public boolean avaBonusCheckValues(CustInvoiceTable custInvoiceTable = this.custInvoiceTable())
{
    boolean retVal;

    retVal = true;

    if(     custInvoiceTable.RecId 
        &&  custInvoiceTable.AVABonusInvoice == NoYes::Yes  )
    {
        if(this.AVABonusSalesBasis == 0.0)
        {
            retVal = checkFailed("@NDX:NXABonusFreeTextBaseValueMissing");
        }
    }

    return retVal;
}

/// <summary>
///    AVA <c>displayCustomerOrAllianceName</c> method.
/// </summary>
/// <returns>
///     <c>CustName</c> as type
/// </returns>
[SysClientCacheDataMethodAttribute(true)]
public display CustName displayCustomerOrAllianceName()
{
    CustName    retVal;

    if(this.AVABonusAllocationBase == AVABonusAllocationBase::Customer)
    {
        retVal = CustTable::find(this.AVABonusCustAccount).name();
    }
    else if(this.AVABonusAllocationBase == AVABonusAllocationBase::Alliance)
    {
        retVal = KCS_TOSTable::find(this.AVABonusAlliance).Description;
    }

    return retVal;
}
